#include <bits/stdc++.h>
using namespace std;

int main() {
    const double PI = acos(-1.0);                  // albo std::numbers::pi (C++20)

    // Trójkąt A(0,0), B(4,0), C(1,3)
    double ax = 0, ay = 0, bx = 4, by = 0, cx = 1, cy = 3;
    double a = hypot(cx - bx, cy - by);            // |BC| = 4.2426
    double b = hypot(cx - ax, cy - ay);            // |AC| = 3.1623
    double c = hypot(bx - ax, by - ay);            // |AB| = 4
    double s = (a + b + c) / 2;
    double area = sqrt(s * (s - a) * (s - b) * (s - c));   // wzór Herona
    cout << fixed << setprecision(4);
    cout << "pole: " << area << '\n';                      // 6.0000

    // Kąt wektora AC względem osi OX: atan2(y, x), wynik w radianach
    double ang = atan2(cy - ay, cx - ax);
    cout << "kat AC: " << ang * 180 / PI << " stopni\n";    // 71.5651

    // Zaokrąglenia
    for (double x : {2.5, -2.5, 2.7, -2.7})
        cout << x << ": floor=" << floor(x) << " ceil=" << ceil(x)
             << " round=" << round(x) << " trunc=" << trunc(x) << '\n';

    // Reszta z dzielenia dla double (operator % działa tylko na intach)
    cout << fmod(7.5, 2) << ' ' << fmod(-7.5, 2) << ' ' << remainder(7.5, 2) << '\n'; // 1.5 -1.5 -0.5

    // Logarytmy i potęgi
    cout << log(exp(2.0)) << ' ' << log2(1024.0) << ' ' << log10(1e6) << ' '
         << log(81.0) / log(3.0) << '\n';                  // 2 10 6 4 (przybliżenia!)
    cout << pow(2.0, 0.5) << ' ' << cbrt(-27.0) << '\n';   // 1.4142 -3.0000

    // NaN i nieskończoność
    double bad = sqrt(-1.0), big = exp(1000.0);
    cout << isnan(bad) << ' ' << isinf(big) << ' ' << isfinite(area) << '\n';  // 1 1 1
    cout << (bad == bad) << '\n';                          // 0 — NaN nie jest równy niczemu
}

