#include <bits/stdc++.h>
using namespace std;

int cmpInt(const void* a, const void* b) {
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);                  // NIE: x - y (przepełnienie)
}

int main() {
    char s[100] = "ala ma kota";
    char t[100];
    int n = strlen(s);                         // 11 — licz RAZ, nie w warunku pętli
    strcpy(t, s);                              // t = "ala ma kota"
    strcat(t, "!");                            // t = "ala ma kota!"
    cout << n << ' ' << t << '\n';
    cout << (strcmp("abc", "abd") < 0) << ' ' << (strcmp(s, t) == 0) << '\n';   // 1 0

    const char* p = strstr(s, "ma");           // wskaźnik na "ma kota" albo nullptr
    if (p) cout << "ma na pozycji " << p - s << '\n';             // 4
    const char* q = strchr(s, 'k');            // pierwsze 'k'
    cout << "k na pozycji " << q - s << '\n';                     // 7

    int a[5] = {5, 3, 9, 1, 7}, b[5];
    memcpy(b, a, sizeof a);                    // kopiuje 5 intów (rozmiar w bajtach!)
    memmove(a + 1, a, 4 * sizeof(int));        // przesunięcie w prawo — obszary się nakładają
    cout << a[0] << a[1] << a[2] << ' ' << (memcmp(b, a, sizeof a) != 0) << '\n';  // 553 1
    memset(b, 0, sizeof b);                    // zerowanie (bezpieczne: 0 i -1)

    // Konwersje (cstdlib)
    cout << atoi("123") + 1 << ' ' << atoll("9000000000") << ' ' << atof("2.5") * 2 << '\n'; // 124 9000000000 5
    cout << strtol("ff", nullptr, 16) << ' ' << strtol("1011", nullptr, 2) << ' '
         << strtoll("-z", nullptr, 36) << '\n';                                         // 255 11 -35
    char* end;
    long v = strtol("42abc", &end, 10);        // v = 42, end wskazuje na "abc"
    cout << v << " reszta: " << end << '\n';

    div_t d = div(17, 5);
    cout << d.quot << ' ' << d.rem << ' ' << llabs(-5000000000LL) << '\n';  // 3 2 5000000000

    int arr[] = {4, -2, 7, 0};
    qsort(arr, 4, sizeof(int), cmpInt);        // w C++ prościej: sort(arr, arr + 4)
    for (int x : arr) cout << x << ' ';        // -2 0 4 7
    cout << '\n';
    exit(0);                                   // jak return 0 z main, ale działa z dowolnej funkcji
}

