using namespace std;

int main() {
    // --- Wyjście: manipulatory ---
    double x = 3.14159;
    cout << fixed << setprecision(2) << x << '\n';                  // 3.14
    cout << scientific << x << '\n';                                // 3.14e+00
    cout << defaultfloat << setprecision(6) << x << '\n';           // 3.14159
    cout << '[' << setw(6) << 42 << ']' << '\n';                    // [    42]
    cout << '[' << left << setw(6) << 42 << ']' << right << '\n';   // [42    ]
    cout << setfill('0') << setw(5) << 42 << '\n';                  // 00042
    cout << internal << setw(6) << -42 << setfill(' ') << right << '\n';  // -00042
    cout << boolalpha << (2 > 1) << ' ' << noboolalpha << (2 > 1) << '\n'; // true 1
    cout << showpos << 5 << ' ' << -5 << noshowpos << '\n';         // +5 -5
    cout << hex << 255 << ' ' << uppercase << 255 << ' ' << showbase << 255 << '\n'; // ff FF 0XFF
    cout << nouppercase << noshowbase << dec;                       // przywróć
    cout << oct << 8 << dec << ' ' << 8 << '\n';                    // 10 8
    cout << showpoint << 2.0 << noshowpoint << '\n';                // 2.00000

    // --- Wejście: stan strumienia (na istringstream, z cin działa tak samo) ---
    istringstream in("12 abc 7\nreszta linii\nX");
    int a, b;
    in >> a;                          // 12
    in >> b;                          // porażka: "abc" to nie liczba → failbit
    cout << a << ' ' << in.fail() << '\n';                          // 12 1
    in.clear();                       // zdejmij flagi błędu
    string word;
    in >> word >> b;                  // "abc", 7
    in.ignore(numeric_limits<streamsize>::max(), '\n');            // pomiń resztę wiersza
    string line;
    getline(in, line);                // "reszta linii"
    cout << word << ' ' << b << " [" << line << "]\n";
    cout << (char)in.peek() << '\n';  // X — podgląd bez zjadania
    char c = in.get();                // X
    in.unget();                       // oddaj znak
    in >> c;                          // znów X
    in >> c;                          // koniec danych → eof + fail, c bez zmian
    cout << c << ' ' << in.eof() << ' ' << (bool)in << '\n';      // X 1 0
}

