#include <bits/stdc++.h>
using namespace std;

int main() {
    // 1) Zapis do pliku
    ofstream out("dane.txt");                   // domyślnie: utwórz / wyczyść
    if (!out.is_open()) { cerr << "nie da sie otworzyc\n"; return 1; }
    out << "3\n10 20 30\nAla,ma,kota\n";
    out.close();                                // zapisuje bufor; potrzebne przed ponownym otwarciem

    ofstream app("dane.txt", ios::app);         // dopisywanie na końcu
    app << "7 8\n";
    app.close();

    // 2) Odczyt z pliku — dokładnie jak z cin
    ifstream in("dane.txt");
    int n;
    in >> n;
    vector<int> v(n);
    for (int& x : v) in >> x;
    string csv;
    getline(in >> ws, csv);                     // ws zjada '\n' po liczbach → "Ala,ma,kota"

    // 3) Dzielenie po przecinku: istringstream + getline z separatorem
    istringstream parts(csv);
    string tok;
    vector<string> words;
    while (getline(parts, tok, ',')) words.push_back(tok);

    // 4) Reszta pliku do EOF: while (in >> x), nie while (!in.eof())
    int x, rest = 0;
    while (in >> x) rest += x;                  // 7 + 8

    // 5) Budowanie napisu: ostringstream
    ostringstream os;
    os << "suma=" << accumulate(v.begin(), v.end(), 0) << " slow=" << words.size() << " reszta=" << rest;
    cout << os.str() << '\n';                   // suma=60 slow=3 reszta=15

    // 6) Jeden stringstream wiele razy: str(nowa_treść) + clear()
    stringstream ss;
    for (string line : {"1 2 3", "4 5"}) {
        ss.str(line);
        ss.clear();                             // bez tego po pierwszym wierszu flaga EOF blokuje odczyt
        int s = 0, y;
        while (ss >> y) s += y;
        cout << s << ' ';                       // 6 9
    }
    cout << '\n';
    remove("dane.txt");                         // <cstdio>: usuń plik testowy
}

