#include <bits/stdc++.h>
using namespace std;
using namespace std::chrono;

struct Timer {
    steady_clock::time_point start = steady_clock::now();
    double sec() const { return duration<double>(steady_clock::now() - start).count(); }
    long long ms() const { return duration_cast<milliseconds>(steady_clock::now() - start).count(); }
};

int main() {
    Timer t;                                         // start stopera
    clock_t c0 = clock();                            // czas procesora (ctime)

    // Heurystyka poprawiana aż do ~0.3 s ("ucieczka" przed limitem czasu)
    mt19937 rng(steady_clock::now().time_since_epoch().count());
    const double LIMIT = 0.3;                        // z dużym zapasem względem limitu zadania
    long long best = LLONG_MAX, iters = 0;
    while (true) {
        if ((++iters & 1023) == 0 && t.sec() > LIMIT) break;   // zegar co 1024 obroty — now() też kosztuje
        long long cand = rng() % 1000000;            // tu: kolejna próba heurystyki
        best = min(best, cand);
    }
    cout << "najlepszy: " << best << ", prob: " << iters << '\n';

    // Pomiar jednego fragmentu w mikrosekundach
    auto t1 = steady_clock::now();
    long long s = 0;
    for (int i = 0; i < 10000000; i++) s += i % 7;
    auto t2 = steady_clock::now();
    cout << "petla: " << duration_cast<microseconds>(t2 - t1).count() << " us (s=" << s << ")\n";

